      "name": "Broche de Blindagem",
      "description": "Esta joia de prata ou ouro é adornada com imagens em miniatura de escudos de pipa e pode ser usada para prender um manto ou capa.\nO broche absorve automaticamente magias de mísseis mágicos direcionados a você. Um broche de escudo pode absorver 30 mísseis mágicos individuais antes de derreter e se tornar inútil. Às vezes, quando encontrado, um broche de blindagem já absorveu vários mísseis.",
