      "description": "Cada ficha de pena parece ser uma simples pena de algum pássaro exótico. A haste da pena, mergulhada em ouro, contém uma única runa arcana. Ativar uma ficha de pena faz com que ela se transforme em outro objeto, que então pode ser usado normalmente para esse objeto. Cada pena pode ser ativada apenas uma vez, com a maioria delas tornando-se permanentemente o item em sua descrição.\nAtive um ataque com uma arma de longo alcance\nQuando esta pena é ativada, ela imediatamente se transforma em um azevinho vivo, preenchendo um único quadrado. Esta bucha pode fornecer cobertura padrão. Além disso, o arbusto tem 2d4 bagas vermelhas brilhantes. Embora as bagas de azevinho sejam geralmente venenosas, essas bagas são infundidas com magia benéfica. Você pode colher e comer uma fruta como uma ação de Interação para recuperar 1 Ponto de Vida. Uma vez colhida do arbusto, uma baga se torna não-mágica depois de alguns segundos, então ela não cura você se você não comê-la durante sua ação de Interagir.\nSe ativada no solo, a planta continua a crescer e prosperar (embora não produza mais frutos curativos). Se ativado em outro lugar, ele murcha e morre em 1d4.",
