      "name": "Poção do Sopro do Dragão de Prata (Adulto)",
      "description": "Este líquido contém sangue de um dragão prateado. Por 1 hora depois de absorver a mistura, você pode liberar um sopro de dragão de prata. A potência do sopro depende do tipo da poção, com base na idade do dragão cujo sangue foi usado para fazer a poção.\nExalar o sopro do dragão usa uma única ação. Você cria um cone de frio de 4,5 metros que causa 6d6 de dano de frio. Todas as criaturas na área devem tentar um teste de salvamento (reflexo, dc:29, básico, nome: Poção de Sopro do Dragão de Prata Adulto, opções: efeito de área).\nDepois de usar o sopro, você não poderá fazê-lo novamente por 1d4.",
