      "name": "Poção do Sopro do Dragão Verde (Wyrm)",
      "description": "Este líquido contém sangue de um dragão verde. Por 1 hora depois de absorver a mistura, você pode liberar o sopro de um dragão verde. A potência do sopro depende do tipo da poção, com base na idade do dragão cujo sangue foi usado para fazer a poção.\nExalar o sopro do dragão usa uma única ação. Você cria um cone de veneno de 4,5 metros que causa 10d6 de dano de veneno. Todas as criaturas na área devem tentar um teste de salvamento (fortitude, dc:37, básico, nome:Poção de Sopro do Dragão Verde da Wyrm, opções:efeito de área).\nDepois de usar o sopro, você não poderá fazê-lo novamente por 1d4.",
