      "description": "Esta corda de seda mede 50 pés (15 metros) de comprimento e é capaz de suportar até 3.000 libras. Se a corda for cortada, apenas a parte restante mais longa manterá sua magia.\nAtive 1 interação\nFrequência uma vez por hora\nEfeito Você segura uma ponta da corda e aponta para um destino. A corda é animada por 1 minuto, movendo-se 10 pés (3 metros) por rodada até chegar ao destino ou ficar sem comprimento. A corda pode mover-se através de qualquer superfície horizontal ou vertical não prejudicial, mas não pode estender-se para cima sem uma superfície para apoiá-la. A qualquer momento enquanto a corda é animada, você pode usar uma ação Interagir para mexer a corda, dando-lhe um dos seguintes comandos: parar no lugar, prender firmemente ao objeto disponível mais próximo, separar-se de um objeto ou dar um nó ou desamarrar-se.",
