      "description": "Ative 1 interação\nDuração 8 horas\nEsta máscara larga e descartável foi projetada para ser colocada sobre a boca e o nariz e seu filtro alquímico ativado com uma mão. Uma vez ativada, a máscara aguça os odores, proporcionando um aroma impreciso com a linha 60 pés (18 metros). Você não pode usar outras máscaras enquanto estiver usando uma máscara de cão de caça.\nQuando você usa Sobrevivência para Rastrear uma criatura pelo seu cheiro, seu bônus de proficiência é igual ao seu nível mesmo se você não estiver treinado, e a máscara lhe concede +3 de bônus de item em seu teste de Sobrevivência. O Mestre define a CD de Sobrevivência com base na capacidade da área de reter odores, e não em pistas visuais, como é normal ao usar odores.\nEfeito: Máscara Bloodhound (Maior)",
