      "name": "Capa Venenosa Tipo IV",
      "description": "Esta capa de aparência inócua está associada a um tipo de veneno, definido na criação da capa. Muitas vezes aparece como um manto clandestino ou um manto de morcego para quem não sabe. Ao investir esta capa, você perde qualquer resistência ao dano venenoso, e sempre que sofre dano perfurante ou cortante em combate, você fica exposto ao tipo de veneno associado à capa venenosa sem início, mesmo que não seja um veneno de ferimento. Assim que a maldição for ativada pela primeira vez, a capa se fundirá com você.\nCicuta venenosa",
