      "description": "Os quatro tipos diferentes de caixas de pergaminhos de simplicidade geralmente trazem adornos apropriados à sua tradição mágica, como asas angelicais ou letras de outro mundo. No interior, intrincados diagramas rúnicos espiralam para cercar o pergaminho armazenado dentro dele. Um pergaminho colocado dentro da caixa pode ser convertido em energia para lançar magias úteis de forma consistente, dependendo do seu tipo. Você deve ser capaz de lançar magias de uma determinada tradição para usar um pergaminho de simplicidade de um tipo correspondente.\nAtive uma interação\nRequisitos A caixa do pergaminho contém um único pergaminho de uma magia de 1º Rank\nEfeito Você transfere a energia do pergaminho para a caixa do pergaminho, consumindo o pergaminho, e pode imediatamente começar a lançar um das magias da caixa do pergaminho. Se você usar qualquer ação que não seja Conjurar uma magia a partir da caixa do pergaminho após ativar a caixa do pergaminho da simplicidade, o pergaminho e sua energia serão perdidos.\nA caixa de rolagem pode ser usada para lançar Tailwind ou Vanishing Tracks",
